do $$declare source text;begin
 source:=pg_get_functiondef('private.prepare_retention_accounts(integer)'::regprocedure);
 source:=replace(source,'where p.status in(''active'',''suspended'')','where p.actor_kind=''human'' and p.status in(''active'',''suspended'')');execute source;
end$$;
-- Server-only live-session predicate. No browser execution or arbitrary Auth projection.
create function private.npc_session_live(subject uuid,sid uuid) returns boolean language sql stable security definer set search_path='' as $$
 select exists(select 1 from auth.sessions s where s.id=sid and s.user_id=subject and (s.not_after is null or s.not_after>clock_timestamp()))
$$;
revoke all on function private.npc_session_live(uuid,uuid) from public,anon,authenticated;
grant execute on function private.npc_session_live(uuid,uuid) to dartspoint_app;
create function private.guard_npc_privileges() returns trigger language plpgsql set search_path='' as $$begin
 if exists(select 1 from public.profiles p where p.id=new.user_id and p.actor_kind='npc') then raise exception 'npc privileges forbidden';end if;return new;end$$;
revoke all on function private.guard_npc_privileges() from public,anon,authenticated;
create trigger npc_no_staff before insert or update on public.user_roles for each row execute function private.guard_npc_privileges();
create trigger npc_no_vip before insert or update on public.vip_entitlements for each row execute function private.guard_npc_privileges();

-- Room lifecycle and membership transitions permanently invalidate old opportunities.
create function private.npc_room_changed() returns trigger language plpgsql security definer set search_path='' as $$begin
 if new.status is distinct from old.status or new.rules is distinct from old.rules then
  update private.npc_audience set epoch=epoch+1,changed_at=clock_timestamp() where id=new.id::text;
  update private.npc_action_jobs set state='cancelled',reason='context-expired' where room_id=new.id and state in('pending','running');
 end if;return new;end$$;
revoke all on function private.npc_room_changed() from public,anon,authenticated,dartspoint_app;
create trigger npc_room_changed after update on public.community_rooms for each row execute function private.npc_room_changed();
create function private.npc_membership_changed() returns trigger language plpgsql security definer set search_path='' as $$begin
 if new.room_id is distinct from old.room_id or new.visit_id is distinct from old.visit_id then
  update private.npc_action_jobs set state='cancelled',reason='context-expired' where user_id=new.user_id and state in('pending','running');
  delete from private.npc_room_connections where user_id=new.user_id and room_id<>new.room_id;
 end if;return new;end$$;
revoke all on function private.npc_membership_changed() from public,anon,authenticated,dartspoint_app;
create trigger npc_membership_changed after update on public.room_memberships for each row execute function private.npc_membership_changed();
